// Create and populate
scores := map[string]int{
    "Alice": 95,
    "Bob":   87,
}

// Add / update
scores["Charlie"] = 92

// Check existence — don't just read!
score, ok := scores["Dave"]
if !ok {
    fmt.Println("Dave not found")
}

// Delete
delete(scores, "Bob")

// Iterate (order is random!)
for name, score := range scores {
    fmt.Printf("%s: %d\n", name, score)
}

// Common pattern: counting occurrences
words := []string{"go", "is", "go", "fun"}
freq := make(map[string]int)
for _, w := range words {
    freq[w]++  // zero value of int is 0
}
// freq: map[go:2 is:1 fun:1]

import "slices"

// Generic filter — works for any type
func Filter[T any](items []T, predicate func(T) bool) []T {
    result := make([]T, 0)
    for _, item := range items {
        if predicate(item) {
            result = append(result, item)
        }
    }
    return result
}

// Usage
nums := []int{1, 2, 3, 4, 5, 6}
evens := Filter(nums, func(n int) bool { return n%2 == 0 })
// [2, 4, 6]

// Standard library (Go 1.21+)
slices.Sort(nums)
idx, found := slices.BinarySearch(nums, 4)
slices.Contains(nums, 3)  // true

// Generic map keys
func Keys[K comparable, V any](m map[K]V) []K {
    keys := make([]K, 0, len(m))
    for k := range m {
        keys = append(keys, k)
    }
    return keys
}

// Creating slices
nums := []int{1, 2, 3, 4, 5}

// Slice of a slice — shares underlying array!
sub := nums[1:3]  // [2, 3]
sub[0] = 99       // nums is now [1, 99, 3, 4, 5]

// Preallocate for performance
result := make([]string, 0, 1000)
for i := 0; i < 1000; i++ {
    result = append(result, fmt.Sprintf("item_%d", i))
}

// Independent copy
original := []int{1, 2, 3}
clone := make([]int, len(original))
copy(clone, original)
clone[0] = 99  // original is unchanged

// Nil slice vs empty slice
var s1 []int          // nil (len=0, cap=0)
s2 := []int{}        // empty, not nil
s3 := make([]int, 0) // empty, not nil
